html:
{#- Advance Shipping Notice (Supplier Collaboration): what the supplier shipped against which orders, with supplier lots and serial numbers, for the receiving dock. A4, black on white. -#}
{%- macro esc(value) -%}{%- if value is defined and value is not none -%}{{ value|e }}{%- endif -%}{%- endmacro -%}
{%- macro num(value) -%}
{%- set n = frappe.utils.flt(value) -%}
{%- if n == frappe.utils.cint(n) -%}{{ frappe.utils.fmt_money(n, 0) }}{%- else -%}{{ frappe.format(n, {"fieldtype": "Float"}) }}{%- endif -%}
{%- endmacro -%}
<style>
	@page { size: A4; margin: 15mm; }
	.hn-doc { color: #000; background: #fff; font-size: 9pt; line-height: 1.35; }
	.hn-doc table { width: 100%; border-collapse: collapse; }
	.hn-doc th, .hn-doc td { color: #000; background: #fff; border: 1px solid #000; padding: 1.2mm 1.8mm; text-align: left; vertical-align: top; }
	.hn-doc .hn-head { margin-bottom: 4mm; border-bottom: 0.6mm solid #000; }
	.hn-doc .hn-head td { border: 0; padding: 0 0 2mm 0; vertical-align: bottom; }
	.hn-doc .hn-company { font-size: 10pt; font-weight: bold; }
	.hn-doc .hn-title { font-size: 16pt; font-weight: bold; margin-top: 1mm; }
	.hn-doc .hn-right { text-align: right; }
	.hn-doc .hn-label { font-size: 7.5pt; }
	.hn-doc .hn-docno { font-size: 12pt; font-weight: bold; font-family: monospace; }
	.hn-doc .hn-state { display: inline-block; margin-top: 1mm; padding: 0.5mm 2mm; border: 0.5mm solid #000; font-weight: bold; }
	.hn-doc .hn-meta th { width: 18%; }
	.hn-doc .hn-meta td { width: 32%; }
	.hn-doc .hn-section { margin: 5mm 0 1.5mm 0; font-size: 10.5pt; font-weight: bold; }
	.hn-doc .hn-lines { margin-top: 4mm; }
	.hn-doc .hn-lines thead { display: table-header-group; }
	.hn-doc .hn-lines th { border-bottom: 0.5mm solid #000; }
	.hn-doc .hn-lines tr, .hn-doc .hn-sign, .hn-doc .hn-avoid { page-break-inside: avoid; break-inside: avoid; }
	.hn-doc .hn-num { text-align: right; white-space: nowrap; }
	.hn-doc .hn-strong { font-weight: bold; }
	.hn-doc .hn-mono { font-family: monospace; }
	.hn-doc .hn-summary { margin-top: 2mm; text-align: right; }
</style>
<div class="hn-doc">
	<table class="hn-head">
		<tr>
			<td>
				<div class="hn-company">{{ esc(doc.company) }}</div>
				<div class="hn-title">{{ _("Advance Shipping Notice") }}</div>
			</td>
			<td class="hn-right">
				<div class="hn-label">{{ _("Supplier ASN No") }}</div>
				<div class="hn-docno">{{ esc(doc.supplier_asn_no) }}</div>
				<div class="hn-mono">{{ esc(doc.name) }}</div>
				{%- if doc.docstatus == 0 %}<div class="hn-state">{{ _("Draft") }}</div>{% endif %}
				{%- if doc.docstatus == 2 %}<div class="hn-state">{{ _("Cancelled") }}</div>{% endif %}
			</td>
		</tr>
	</table>
	<table class="hn-meta">
		<tr>
			<th>{{ _("Supplier") }}</th>
			<td class="hn-strong">{{ esc(frappe.db.get_value("Supplier", doc.supplier, "supplier_name") or doc.supplier) }}</td>
			<th>{{ _("Plant") }}</th>
			<td>{{ esc(frappe.db.get_value("Plant", doc.plant, "plant_name") or doc.plant) if doc.plant else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Shipped At") }}</th>
			<td>{{ doc.get_formatted("ship_date") }}</td>
			<th>{{ _("Expected Arrival") }}</th>
			<td class="hn-strong">{{ doc.get_formatted("expected_arrival") }}</td>
		</tr>
		<tr>
			<th>{{ _("Carrier") }}</th>
			<td>{{ esc(doc.carrier) }}</td>
			<th>{{ _("Tracking / Waybill No") }}</th>
			<td class="hn-strong hn-mono">{{ esc(doc.tracking_no) }}</td>
		</tr>
		<tr>
			<th>{{ _("Mode") }}</th>
			<td>{{ _(doc.transport_mode) if doc.transport_mode else "" }}</td>
			<th>{{ _("Packages") }}</th>
			<td>{{ doc.packages if doc.packages else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Gross Weight (kg)") }}</th>
			<td>{{ num(doc.gross_weight_kg) if doc.gross_weight_kg else "" }}</td>
			<th>{{ _("Status") }}</th>
			<td>{{ _(doc.status) if doc.status else "" }}</td>
		</tr>
	</table>
	<table class="hn-lines">
		<thead>
			<tr>
				<th class="hn-num">#</th>
				<th>{{ _("Purchase Order") }}</th>
				<th>{{ _("Item") }}</th>
				<th class="hn-num">{{ _("Shipped Qty") }}</th>
				<th>{{ _("Supplier Lot") }}</th>
				<th>{{ _("Serial Nos") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in doc.items %}
			{%- set item = frappe.db.get_value("Item", row.item_code, ["item_name", "stock_uom"], as_dict=True) if row.item_code else none %}
			<tr>
				<td class="hn-num">{{ row.idx }}</td>
				<td>{{ esc(row.purchase_order) }}</td>
				<td>{{ esc(row.item_code) }}{% if item and item.item_name and item.item_name != row.item_code %}<br>{{ esc(item.item_name) }}{% endif %}</td>
				<td class="hn-num">{{ num(row.qty) }} {{ esc(item.stock_uom) if item else "" }}</td>
				<td class="hn-strong hn-mono">{{ esc(row.supplier_lot) }}</td>
				<td class="hn-mono">{{ esc((row.serial_nos or "").split("\n") | map("trim") | reject("equalto", "") | join(", ")) }}</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>
	<div class="hn-summary">
		{{ _("Lines") }}: <span class="hn-strong">{{ doc.items | length }}</span>
		{%- if doc.packages %}
		&nbsp;&nbsp;
		{{ _("Packages") }}: <span class="hn-strong">{{ doc.packages }}</span>
		{%- endif %}
	</div>
</div>
